#include <bits/stdc++.h>
using namespace std;

const int MAXN = 300;
const int ROOM = -1, REAC = -2, BAD_REAC = -3, CAPS = ROOM;

struct Edge {
    int from, to, rev, flow, cap;
    Edge() {}
    Edge(int f, int t, int r, int fl, int c) : from(f), to(t), rev(r), flow(fl), cap(c) {}
    int residual() { return cap - flow; }
};

class MaxFlowImplementation {
public:
    int n;
    vector<Edge*> *graph;
    Edge **parent;
    bool *visited;

    MaxFlowImplementation(int size) {
        n = size;
        graph = new vector<Edge*>[n];
        parent = new Edge*[n];
        visited = new bool[n];
    }

    void clear_graph() {
        for (int i=0; i<n; i++) {
            for (auto e : graph[i]) delete e;
            graph[i].clear();
        }
    }

    void delete_all() {
        clear_graph();
        delete[] parent;
        delete[] visited;
        delete this;
    }

    void create_edge(int s, int t, int capacity) {
        Edge *a = new Edge(s, t, (int)graph[t].size(), 0, capacity);
        Edge *b = new Edge(t, s, (int)graph[s].size(), 0, 0);
        graph[s].push_back(a);
        graph[t].push_back(b);
    }

    void create_bi_edge(int s, int t, int capacity) {
        Edge *a = new Edge(s, t, (int)graph[t].size(), 0, capacity);
        Edge *b = new Edge(t, s, (int)graph[s].size(), 0, capacity);
        graph[s].push_back(a);
        graph[t].push_back(b);
    }

    bool find_augmenting_path(int s, int t) {
        for (int i=0; i<n; i++) {
            parent[i] = nullptr;
            visited[i] = false;
        }
        queue<int> q;
        q.push(s);
        visited[s] = true;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            if (u == t) return true;
            for (auto e : graph[u]) {
                if (!visited[e->to] && e->residual() > 0) {
                    parent[e->to] = e;
                    visited[e->to] = true;
                    q.push(e->to);
                }
            }
        }
        return false;
    }

    int find_flow(int s, int t) {
        int flow = INT_MAX;
        int v = t;
        while (v != s) {
            flow = min(flow, parent[v]->residual());
            v = parent[v]->from;
        }
        v = t;
        while (v != s) {
            parent[v]->flow += flow;
            graph[parent[v]->to][parent[v]->rev]->flow -= flow;
            v = parent[v]->from;
        }
        return flow;
    }

    long long compute_max_flow(int s, int t) {
        int total_flow = 0;
        while (find_augmenting_path(s, t)) {
            total_flow += find_flow(s, t);
        }
        return total_flow;
    }
};

int station[MAXN][MAXN], checkpoint[MAXN][MAXN], poison_map[61][MAXN][MAXN];

struct Coord {
    int x, y, quantity;
    Coord(int a, int b, int c) : x(a), y(b), quantity(c) {}
    bool valid(int N) { return (x >= 0 && x < N && y >= 0 && y < N && station[x][y] == ROOM); }
};

bool is_valid_coord(int x, int y, int N) {
    return Coord(x, y, 0).valid(N);
}

inline bool operator==(const Coord &a, const Coord &b) {
    return (a.x == b.x && a.y == b.y);
}

vector<Coord> evacuees_list, capsules_list;
int moveX[] = {-1, 0, 1, 0};
int moveY[] = {0, -1, 0, 1};

int translate_char_to_int(char ch) {
    if (ch >= '0' && ch <= '9') return ROOM;
    if (ch == 'Y') return REAC;
    if (ch == 'Z') return BAD_REAC;
    return -1;
}

int get_quantity_from_char(char ch) {
    return ch - '0';
}

int shortest_path_bfs(Coord start, Coord end, int N) {
    bitset<MAXN> visited[MAXN];
    queue<pair<int, Coord>> q;
    q.push({0, start});
    visited[start.x][start.y] = 1;
    while (!q.empty()) {
        int t = q.front().first;
        Coord c = q.front().second;
        q.pop();
        if (c == end) return t;
        if (poison_map[t][c.x][c.y]) continue;
        for (int i=0; i<4; i++) {
            Coord n(c.x + moveX[i], c.y + moveY[i], 0);
            if (n.valid(N) && !visited[n.x][n.y]) {
                if (!poison_map[t][n.x][n.y]) {
                    q.push({t + 1, n});
                    visited[n.x][n.y] = 1;
                }
            }
        }
    }
    return 999;
}

void propagate_poison(int x, int y, int T, int N) {
    poison_map[0][x][y] = 1;
    for (int t=1; t<=T; t++) {
        for (int i=0; i<N; i++) {
            for (int j=0; j<N; j++) {
                if (poison_map[t-1][i][j]) {
                    poison_map[t][i][j] = 1;
                    for (int move=0; move<4; move++) {
                        int nx = i + moveX[move], ny = j + moveY[move];
                        if (is_valid_coord(nx, ny, N))
                            poison_map[t][nx][ny] = 1;
                    }
                }
            }
        }
    }
}

int main() {
    int N, T;
    scanf("%d %d", &N, &T);
    char ch;
    Coord bad(0,0,0);
    for (int i=0; i<N; i++) {
        for (int j=0; j<N; j++) {
            scanf(" %c", &ch);
            int val = translate_char_to_int(ch);
            station[i][j] = val;
            if (val == ROOM && get_quantity_from_char(ch))
                evacuees_list.push_back(Coord(i,j,get_quantity_from_char(ch)));
            if (val == BAD_REAC)
                bad = Coord(i,j,0);
        }
    }
    for (int i=0; i<N; i++) {
        for (int j=0; j<N; j++) {
            scanf(" %c", &ch);
            int val = translate_char_to_int(ch);
            if (val == CAPS && get_quantity_from_char(ch)) {
                capsules_list.push_back(Coord(i,j,get_quantity_from_char(ch)));
                checkpoint[i][j] = get_quantity_from_char(ch);
            }
        }
    }
    MaxFlowImplementation *mf_impl = new MaxFlowImplementation(MAXN);
    int sink_node = MAXN - 1;
    for (size_t i=0; i<evacuees_list.size(); i++) {
        mf_impl->create_edge(0, i*2+1, evacuees_list[i].qty);
    }
    for (size_t i=0; i<capsules_list.size(); i++) {
        mf_impl->create_bi_edge(i*2+2, sink_node, capsules_list[i].qty);
    }
    propagate_poison(bad.x, bad.y, T, N);
    for (size_t i=0; i<evacuees_list.size(); i++) {
        for (size_t j=0; j<capsules_list.size(); j++) {
            int t = shortest_path_bfs(evacuees_list[i], capsules_list[j], N);
            if (t <= T) {
                mf_impl->create_bi_edge(i*2+1, j*2+2, 999);
            }
        }
    }
    printf("%lld\n", mf_impl->compute_max_flow(0, sink_node));
    delete mf_impl;
    return 0;
}
